async (options) => {
  await Promise.race([new Promise(ok => requestAnimationFrame(() => requestAnimationFrame(ok))), new Promise(ok => setTimeout(ok,200))]);
  const fontsReady = await Promise.race([document.fonts.ready.then(()=>true), new Promise(ok=>setTimeout(()=>ok(false),3000))]);
  await Promise.race([Promise.all(Array.from(document.images).map(image => image.decode().catch(() => {}))), new Promise(ok=>setTimeout(ok,3000))]);
  window.scrollTo(options.scroll[0], options.scroll[1]);
  let root;
  try { root = options.selector ? document.querySelector(options.selector) : document.documentElement; }
  catch { return {error:'element'}; }
  if (!root) return {error:'element'};
  const bounds = root.getBoundingClientRect();
  const clip = options.selector ? {x:bounds.x+scrollX,y:bounds.y+scrollY,width:bounds.width,height:bounds.height,scale:1} : {x:scrollX,y:scrollY,width:innerWidth,height:innerHeight,scale:1};
  if (clip.width<=0 || clip.height<=0) return {error:'element'};
  if (clip.width>16384 || clip.height>16384) return {error:'large'};
  if (!options.snapshot) return {clip};
  const nodes=[], notes=[]; let textChars=0;
  if(!fontsReady || Array.from(document.fonts).some(font=>font.status!=="loaded")) notes.push("Some page fonts did not load; text uses a browser fallback.");
  const keys=['backgroundColor','backgroundImage','borderRadius','borderTopWidth','borderTopColor','opacity','overflow','color','fontFamily','fontSize','fontWeight','fontStyle','fontOpticalSizing','fontVariationSettings','fontFeatureSettings','textTransform','lineHeight','letterSpacing','textDecorationLine','objectFit','boxShadow','transform','filter'];
  const geometry=r=>({x:r.x+scrollX-clip.x,y:r.y+scrollY-clip.y,width:r.width,height:r.height});
  const readStyle=s=>Object.fromEntries(keys.map(k=>[k,s[k]]));
  const selectorFor=element=>{
    if(element.id) return '#'+CSS.escape(element.id);
    const parts=[];
    for(let e=element;e && e!==document.documentElement;e=e.parentElement) {
      let index=1; for(let s=e.previousElementSibling;s;s=s.previousElementSibling) if(s.tagName===e.tagName) index++;
      parts.unshift(e.tagName.toLowerCase()+':nth-of-type('+index+')');
    }
    return 'html > '+parts.join(' > ');
  };
  const stack=[{element:root,parent:null,depth:0}];
  while(stack.length) {
    const {element,parent,depth}=stack.pop();
    if (nodes.length>=5000 || depth>100) return {error:'large'};
    if (element.nodeType===Node.TEXT_NODE) {
      if (!element.textContent.trim()) continue;
      textChars+=element.length; if(textChars>100000) return {error:"large"};
      const owner=element.parentElement, style=getComputedStyle(owner);
      const range=document.createRange();range.selectNodeContents(element);
      // Preserve line fragments individually, so wrapped text stays at the measured baselines.
      const lines=[];let current=null;
      for(let i=0;i<element.length;i++) {
        range.setStart(element,i);range.setEnd(element,i+1);
        const rect=range.getBoundingClientRect();
        if (!rect.width || !rect.height) continue;
        if(!current || Math.abs(current.y-rect.y)>1) {current={x:rect.x,y:rect.y,width:rect.width,height:rect.height,text:''};lines.push(current);}
        current.width=rect.right-current.x;current.height=Math.max(current.height,rect.height);current.text+=element.textContent[i];
      }
      for(const line of lines) {
        if(nodes.length>=5000) return {error:'large'};
        // Range height is glyph ink; frame top is the line box's top.
        const lineHeight=parseFloat(style.lineHeight)||line.height;
        const r={...line,y:line.y-(lineHeight-line.height)/2,height:lineHeight};
        nodes.push({kind:'text',name:'Text',parent,...geometry(r),text:style.whiteSpace.startsWith('pre')?line.text:line.text.replace(/\s+/g,' '),style:readStyle(style)});
      }
      continue;
    }
    if (!(element instanceof Element) || ['SCRIPT','STYLE','LINK','META','HEAD','NOSCRIPT'].includes(element.tagName)) continue;
    const style=getComputedStyle(element), rect=element===root && !options.selector ? {x:0,y:0,width:innerWidth,height:innerHeight} : element.getBoundingClientRect();
    if(style.display==='none'||style.visibility==='hidden'||style.opacity==='0') continue;
    if(element.tagName==='IFRAME'||element.tagName==='VIDEO'||element.tagName==='CANVAS'||element.tagName==='SVG') {notes.push(element.tagName.toLowerCase()+': live or vector content is not converted.');continue;}
    const name=element.tagName.toLowerCase()+(element.id?'#'+element.id:'');
    if(rect.width<=0||rect.height<=0) {
      for(const child of Array.from(element.childNodes).reverse()) stack.push({element:child,parent,depth:depth+1});
      continue;
    }
    const at=nodes.length;
    const node={kind:element instanceof HTMLImageElement?'image':'frame',name,selector:selectorFor(element),parent,...geometry(rect),style:readStyle(style)};
    if(element instanceof HTMLImageElement) {
      try {const canvas=document.createElement('canvas');canvas.width=element.naturalWidth;canvas.height=element.naturalHeight;
        if(canvas.width*canvas.height>16000000) return {error:'large'};
        canvas.getContext('2d').drawImage(element,0,0);node.image=canvas.toDataURL('image/png');}
      catch {notes.push(name+': image pixels could not be read.');}
    }
    if(style.position==='fixed'||style.position==='sticky') notes.push(name+': imported at its current scroll position.');
    for(const pseudo of ['::before','::after']) {
      const p=getComputedStyle(element,pseudo);if(!['none','normal',''].includes(p.content)) notes.push(name+': generated content is not converted.');
    }
    if(element===root && !options.selector) {
      Object.assign(node,{x:0,y:0,width:clip.width,height:clip.height});
      if(node.style.backgroundColor==='rgba(0, 0, 0, 0)') node.style.backgroundColor='rgb(255, 255, 255)';
    }
    nodes.push(node);
    if(node.kind==='frame') for(const child of Array.from(element.childNodes).reverse()) stack.push({element:child,parent:at,depth:depth+1});
  }
  return {clip,dom:{version:1,width:clip.width,height:clip.height,nodes,notes:Array.from(new Set(notes))}};
}
